import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { projectLabelToView, MULTI_VIEW_NAMES } from '../lib/layout-optimizer.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
function parseArgs(argv) { const options={experts:path.join(root,'experiments','moe_expert_layouts_test11.json'),output:path.join(root,'experiments','moe_expert_preview_bundle_test11.json')}; for(let i=0;i<argv.length;i+=1) if(argv[i].startsWith('--')){const k=argv[i].slice(2);options[k]=argv[i+1]&&!argv[i+1].startsWith('--')?argv[++i]:true;} return options; }
async function readJson(file){return JSON.parse(await fs.readFile(file,'utf8'));}
function projected(labels,bounds,view){return labels.map(label=>{const item=projectLabelToView(label,bounds,view); return {id:label.id,text:label.text,anchor:{x:Number(item.anchor.x.toFixed(6)),y:Number(item.anchor.y.toFixed(6)),depth:Number(item.anchor.depth.toFixed(6))},center:{x:Number(item.center.x.toFixed(6)),y:Number(item.center.y.toFixed(6)),depth:Number(item.center.depth.toFixed(6))},width:Number(item.width.toFixed(6)),height:Number(item.height.toFixed(6)),style:label.layout_style_expert||null,perturbation:'expert_'+(label.layout_style_expert||'unknown')};});}
async function main(){const options=parseArgs(process.argv.slice(2));const bundle=await readJson(path.resolve(String(options.experts)));const manifest=await readJson(path.join(root,'experiments','dataset_manifest.json'));const byKey=new Map(manifest.samples.map(s=>[`${s.category}/${s.sample_id}`,s]));const rows=[];for(const row of bundle.rows){const sample=byKey.get(`${row.category}/${row.sample_id}`);const viewFiles=Object.fromEntries(MULTI_VIEW_NAMES.map(view=>[view,sample?.views?.files?.find(file=>file.toLowerCase().includes(`-${view}.png`))||null]));const candidates=Object.entries(row.experts).map(([style,expert])=>({candidate_id:`${row.category}_${row.sample_id}_${style}`,mode:style,style,metrics:expert.metrics,labels:expert.labels,projected:Object.fromEntries(MULTI_VIEW_NAMES.map(view=>[view,projected(expert.labels,row.bounds,view)]))}));rows.push({category:row.category,sample_id:row.sample_id,split:row.split,source_obj:sample?.input?.source_obj||null,view_files:viewFiles,bounds:row.bounds,candidates});}const result={version:'moe_expert_preview_bundle_v1',generated_at:new Date().toISOString(),image_order:MULTI_VIEW_NAMES,rows};await fs.writeFile(path.resolve(String(options.output)),JSON.stringify(result,null,2)+'\n','utf8');console.log(JSON.stringify({ok:true,output:path.relative(root,path.resolve(String(options.output))).split(path.sep).join('/'),samples:rows.length,candidates:rows.reduce((n,r)=>n+r.candidates.length,0)},null,2));}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))main().catch(e=>{console.error(e);process.exit(1);});
